SELECT r.id,r.content_generation,r.source_revision,COALESCE((SELECT IF(s.id IS NULL,'',SHA2(CAST(JSON_ARRAY('album',r.id,s.source,s.source_album_id,r.resource_kind,SHA2(COALESCE(r.remote_url,''),256)) AS CHAR),256)) FROM album_source_refs s WHERE r.album_source_ref_id=s.id),''),r.status,r.claim_generation,COALESCE(r.running_batch_id,''),r.reference_sha256,r.reference_size_bytes,r.local_content_generation,r.local_target_revision,r.local_skip_generation,r.local_skip_target_revision,r.local_skip_baseline,r.local_skip_reason,COALESCE(r.local_path,''),COALESCE(r.checksum,''),r.size_bytes
FROM album_resources r WHERE r.id=? FOR UPDATE
